package com.edufox.schoolerp.fee.report.fee_reports;

import com.edufox.schoolerp.common.persistence.SessionResolver;
import com.edufox.schoolerp.fee.report.fee_booklet.*;
import com.edufox.schoolerp.fee.shared.fee_core.*;
import com.edufox.schoolerp.fee.update.fee_update.*;
import com.edufox.schoolerp.fee.update.optional_fee.*;
import com.edufox.schoolerp.fee.work.fee_work.*;

import io.jsonwebtoken.Claims;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.util.*;

/** Read-only Java report queries replacing the legacy Fee report procedures. */
@RestController
@RequestMapping("/api/fees/report-data")
@RequiredArgsConstructor
@PreAuthorize("hasRole('FACULTY')")
public class FeeReportController {
    private final JdbcTemplate jdbc;

    private static Claims claims(Authentication a){return (Claims)a.getDetails();}
    private static String school(Authentication a){return text(claims(a).get("schoolId",String.class));}
    private static String text(Object v){return v==null?"":String.valueOf(v).trim();}
    private String session(Object requested,String sc){return SessionResolver.resolve(jdbc, requested, sc);}

    @GetMapping("/{report}")
    public List<Map<String,Object>> report(@PathVariable String report,@RequestParam(required=false)String session,@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(required=false)Integer classId,@RequestParam(required=false)Integer feeTypeId,@RequestParam(required=false)Integer installmentNo,@RequestParam(required=false)String admissionNo,@RequestParam(required=false)String status,@RequestParam(required=false)String studentType,@RequestParam(required=false)String payMode,@RequestParam(required=false)String category,Authentication a){
        String sc=school(a),ses=session(session,sc),r=report.toLowerCase(Locale.ROOT);return switch(r){
            case "budget" -> budget(sc,ses,feeTypeId,studentType);
            case "classwise" -> classwise(sc,ses,classId,feeTypeId);
            case "concession-group" -> concessionGroup(sc,ses,classId,admissionNo);
            case "concession" -> concession(sc,ses,classId,admissionNo);
            case "daily-collection" -> collection(sc,ses,from,to,classId,feeTypeId,admissionNo);
            case "daily-deposit" -> dailyDeposit(sc,ses,from,to,feeTypeId,payMode,category);
            case "defaulter" -> defaulter(sc,ses,classId,installmentNo,feeTypeId,admissionNo);
            case "reconciliation", "sub-reconciliation" -> reconciliation(sc,ses,from,to,admissionNo,status);
            case "installment-defaulter" -> installmentDefaulter(sc,ses,classId,installmentNo,feeTypeId,admissionNo);
            case "late-fee" -> lateFee(sc,ses,classId,admissionNo);
            case "payment-response" -> paymentResponse(sc,ses,from,to,status,admissionNo);
            case "student-summary" -> studentSummary(sc,ses,admissionNo);
            default -> throw new IllegalArgumentException("Unknown fee report: "+report);
        };}

    private List<Map<String,Object>> budget(String sc,String ses,Integer type,String studentType){int feeType=type==null?0:type;String q="SELECT l.installment_no AS installmentNo,SUM(COALESCE(l.head_amount,0)) AS charges,SUM(COALESCE(l.concession,0)) AS concession,SUM(COALESCE(l.receive_amount,0)) AS paid,SUM(COALESCE(l.balance,0)) AS remaining FROM fee_student_ledger l JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id LEFT JOIN configuration cfg ON cfg.school_id=l.school_id WHERE l.school_id=? AND l.session=?";List<Object>p=new ArrayList<>(List.of(sc,ses));if(feeType==0){q+=" AND l.fee_type_id NOT IN (CASE WHEN COALESCE(cfg.considerTransport,0)=0 THEN 6 ELSE 0 END,CASE WHEN COALESCE(cfg.considerHostel,0)=0 THEN 7 ELSE 0 END)";}else{q+=" AND l.fee_type_id=?";p.add(feeType);}String st=text(studentType).toLowerCase(Locale.ROOT);if("registered".equals(st)||"withdrawn".equals(st)){q+=" AND LOWER(sm.status)=?";p.add(st);}else{q+=" AND LOWER(sm.status) IN ('registered','withdrawn')";}return jdbc.queryForList(q+" GROUP BY l.installment_no ORDER BY l.installment_no",p.toArray());}
    private List<Map<String,Object>> classwise(String sc,String ses,Integer classId,Integer type){String q="SELECT COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,l.fee_type_id AS feeTypeId,SUM(COALESCE(l.payable,0)) AS payable,SUM(COALESCE(l.receive_amount,0)) AS received,SUM(COALESCE(l.balance,0)) AS balance,COUNT(DISTINCT l.stu_id) AS students FROM fee_student_ledger l JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE l.school_id=? AND l.session=?";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(type!=null){q+=" AND l.fee_type_id=?";p.add(type);}return jdbc.queryForList(q+" GROUP BY cn.class_name,cl.section,l.fee_type_id ORDER BY className,section",p.toArray());}
    private List<Map<String,Object>> concessionGroup(String sc,String ses,Integer classId,String adm){String q="SELECT COALESCE(g.Group_name,'') AS groupName,sg.group_code AS groupCode,COUNT(DISTINCT sg.stu_id) AS students,SUM(COALESCE(l.concession,0)) AS concession,SUM(COALESCE(l.payable,0)) AS payable,SUM(COALESCE(l.receive_amount,0)) AS received,SUM(COALESCE(l.balance,0)) AS balance FROM fee_student_con_group sg LEFT JOIN concession_group_name g ON g.school_id=sg.school_id AND g.session=sg.session AND g.group_code=sg.group_code LEFT JOIN fee_student_ledger l ON l.school_id=sg.school_id AND l.session=sg.session AND l.stu_id=sg.stu_id WHERE sg.school_id=? AND sg.session=? AND sg.status=1";List<Object>p=new ArrayList<>(List.of(sc,ses));if(!text(adm).isBlank()){q+=" AND EXISTS(SELECT 1 FROM TB_StudentMaster sm WHERE sm.school_id=sg.school_id AND sm.stu_id=sg.stu_id AND sm.registration_no LIKE ?)";p.add("%"+text(adm)+"%");}if(classId!=null){q+=" AND EXISTS(SELECT 1 FROM TB_StudentMaster sm WHERE sm.school_id=sg.school_id AND sm.stu_id=sg.stu_id AND sm.class_id=?)";p.add(classId);}return jdbc.queryForList(q+" GROUP BY g.Group_name,sg.group_code ORDER BY groupName",p.toArray());}
    private List<Map<String,Object>> concession(String sc,String ses,Integer classId,String adm){String q="SELECT sm.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,c.inst_no AS installmentNo,COALESCE(h.fee_head,'') AS feeHead,c.con_type AS concessionType,c.con_charge AS concession,c.con_per AS percentage,c.remark FROM fee_concession c JOIN TB_StudentMaster sm ON sm.school_id=c.school_id AND sm.stu_id=c.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id LEFT JOIN fee_head_master h ON h.school_id=c.school_id AND h.session=c.session AND h.fee_head_id=c.fee_head_id WHERE c.school_id=? AND c.session=? AND c.status=1";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(!text(adm).isBlank()){q+=" AND sm.registration_no LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" ORDER BY className,section,studentName,c.inst_no",p.toArray());}
    private List<Map<String,Object>> collection(String sc,String ses,String from,String to,Integer classId,Integer type,String adm){String q="SELECT p.row_id AS id,p.admission_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,COALESCE(p.pay_date,p.paymentdate,p.deposit_date) AS paymentDate,COALESCE(p.pay_mode,p.mop,'') AS payMode,p.fee_type AS feeType,p.amount,p.receipt_no AS receiptNo,p.deposit_by AS depositBy,p.status FROM fee_payment_detail p LEFT JOIN TB_StudentMaster sm ON sm.school_id=p.school_id AND (CAST(sm.stu_id AS varchar(50))=p.stu_id OR sm.registration_no=p.admission_no) LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE p.school_id=? AND p.session=?";List<Object>p=new ArrayList<>(List.of(sc,ses));if(!text(from).isBlank()){q+=" AND TRY_CONVERT(date,COALESCE(p.pay_date,p.paymentdate,p.deposit_date))>=TRY_CONVERT(date,?)";p.add(from);}if(!text(to).isBlank()){q+=" AND TRY_CONVERT(date,COALESCE(p.pay_date,p.paymentdate,p.deposit_date))<=TRY_CONVERT(date,?)";p.add(to);}if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(type!=null){q+=" AND TRY_CONVERT(int,p.fee_type_id)=?";p.add(type);}if(!text(adm).isBlank()){q+=" AND p.admission_no LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" ORDER BY paymentDate DESC,p.row_id DESC",p.toArray());}
    private List<Map<String,Object>> dailyDeposit(String sc,String ses,String from,String to,Integer type,String payMode,String category){StringBuilder q=new StringBuilder("WITH P AS (SELECT p.* FROM fee_payment_detail p WHERE p.school_id=? AND LOWER(COALESCE(p.status,''))='active' AND p.financial_year=? AND TRY_CONVERT(date,p.paymentdate) BETWEEN TRY_CONVERT(date,?) AND TRY_CONVERT(date,?)), H AS (SELECT stu_id,uid,receipt_no,school_id,session,STRING_AGG(CAST(inst_no AS varchar(30)),',') AS installmentNo,SUM(TRY_CONVERT(decimal(18,2),receive_amt)) AS receivedAmount FROM stu_headwise_deposit WHERE school_id=? AND session=? AND status='active' GROUP BY stu_id,uid,receipt_no,school_id,session), L AS (SELECT stu_id,uid,session,school_id,SUM(TRY_CONVERT(decimal(18,2),inst_late_fee)) AS lateFee FROM fee_installmentwise_deposit WHERE school_id=? AND session=? AND status='active' GROUP BY stu_id,uid,session,school_id), A AS (SELECT uid,school_id,SUM(COALESCE(balance,0)) AS advanceFee FROM advance_fee WHERE school_id=? AND balance<>0 GROUP BY uid,school_id) SELECT CONVERT(varchar(10),CAST(p.paymentdate AS date),23) AS dateKey,CONVERT(varchar(20),CAST(p.paymentdate AS date),106) AS depositedDate,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS name,sm.registration_no AS admissionNo,sm.FeeBookNo AS feeBookNo,COALESCE(cn.class_name,'')+' ['+COALESCE(cl.section,'')+']' AS className,COALESCE(p.mop,'') AS mop,h.receivedAmount,COALESCE(a.advanceFee,0) AS advanceFee,COALESCE(l.lateFee,0) AS lateFee,h.receivedAmount+COALESCE(l.lateFee,0) AS receivedWithLate,h.receivedAmount+COALESCE(l.lateFee,0)+COALESCE(a.advanceFee,0) AS totalReceived,COALESCE(h.receipt_no,p.receiptno) AS receiptNo,h.installmentNo,p.financial_year AS session,COALESCE(p.feeremark,'') AS remark,COALESCE(sm.isnew,'0') AS isNew FROM P p JOIN H h ON h.school_id=p.school_id AND h.uid=p.uid AND h.receipt_no=p.receiptno LEFT JOIN L l ON l.school_id=h.school_id AND l.session=h.session AND l.uid=h.uid AND l.stu_id=h.stu_id LEFT JOIN A a ON a.school_id=h.school_id AND a.uid=h.uid JOIN TB_StudentMaster sm ON sm.school_id=h.school_id AND sm.stu_id=h.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE 1=1");List<Object>p=new ArrayList<>(List.of(sc,ses,from,to,sc,ses,sc,ses,sc));if(type!=null&&type==6){q.append(" AND p.fee_type='6'");}if(!text(payMode).isBlank()&&!"0".equals(payMode)){q.append(" AND p.mop=?");p.add(payMode);}if("0".equals(category)||"1".equals(category)){q.append(" AND COALESCE(sm.isnew,'0')=?");p.add(category);}q.append(" ORDER BY CAST(p.paymentdate AS date),p.mop,receiptNo");List<Map<String,Object>>details=jdbc.queryForList(q.toString(),p.toArray());return daywiseRows(details,"0".equals(text(payMode))||text(payMode).isBlank());}

    /** Adds the same mode/date/grand-total rows that the legacy sub-report emitted. */
    private List<Map<String,Object>> daywiseRows(List<Map<String,Object>> details,boolean includeModeTotals){
        List<Map<String,Object>> out=new ArrayList<>();
        Map<String,List<Map<String,Object>>> byDate=new LinkedHashMap<>();
        for(Map<String,Object> d:details)byDate.computeIfAbsent(text(d.get("dateKey")),k->new ArrayList<>()).add(d);
        List<Map<String,Object>> all=new ArrayList<>();
        for(List<Map<String,Object>> dateRows:byDate.values()){
            out.addAll(dateRows);
            all.addAll(dateRows);
            if(includeModeTotals){
                Map<String,List<Map<String,Object>>> byMode=new LinkedHashMap<>();
                for(Map<String,Object> d:dateRows)byMode.computeIfAbsent(text(d.get("mop")),k->new ArrayList<>()).add(d);
                for(Map.Entry<String,List<Map<String,Object>>> e:byMode.entrySet())out.add(daywiseSummary(e.getValue(),2,e.getKey()+" Total"));
            }
            out.add(daywiseSummary(dateRows,3,"Total"));
        }
        if(!all.isEmpty())out.add(daywiseSummary(all,4,"Grand Total"));
        List<Map<String,Object>> normalized=new ArrayList<>();
        int serial=1;
        for(Map<String,Object> row:out){
            Map<String,Object> m=new LinkedHashMap<>(row);
            if(!m.containsKey("rowKind")){m.put("rowKind",1);m.put("serialNo",serial++);}else m.putIfAbsent("serialNo",null);
            normalized.add(m);
        }
        return normalized;
    }

    private Map<String,Object> daywiseSummary(List<Map<String,Object>> rows,int kind,String label){
        Map<String,Object> m=new LinkedHashMap<>();
        Map<String,Object> first=rows.get(0);
        m.put("dateKey",text(first.get("dateKey")));m.put("depositedDate",text(first.get("depositedDate")));m.put("name",label);
        m.put("admissionNo","");m.put("feeBookNo","");m.put("className","");m.put("mop",kind==2?label.replace(" Total",""):"");
        m.put("receivedAmount",sum(rows,"receivedAmount"));m.put("advanceFee",sum(rows,"advanceFee"));m.put("lateFee",sum(rows,"lateFee"));
        m.put("receivedWithLate",sum(rows,"receivedWithLate"));m.put("totalReceived",sum(rows,"totalReceived"));m.put("receiptNo","");
        m.put("installmentNo","");m.put("session",text(first.get("session")));m.put("remark","");m.put("isNew","");m.put("rowKind",kind);m.put("serialNo",null);return m;
    }

    private BigDecimal sum(List<Map<String,Object>> rows,String key){BigDecimal total=BigDecimal.ZERO;for(Map<String,Object> r:rows)total=total.add(decimal(r.get(key)));return total;}
    private BigDecimal decimal(Object v){try{return v==null||text(v).isBlank()?BigDecimal.ZERO:new BigDecimal(text(v));}catch(NumberFormatException e){return BigDecimal.ZERO;}}
    private List<Map<String,Object>> defaulter(String sc,String ses,Integer classId,Integer inst,Integer type,String adm){String q="SELECT sm.registration_no AS admissionNo,sm.stu_id AS studentId,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,SUM(COALESCE(l.payable,0)) AS payable,SUM(COALESCE(l.receive_amount,0)) AS received,SUM(COALESCE(l.balance,0)) AS balance FROM fee_student_ledger l JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE l.school_id=? AND l.session=? AND COALESCE(l.balance,0)>0";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(inst!=null){q+=" AND l.installment_no=?";p.add(inst);}if(type!=null){q+=" AND l.fee_type_id=?";p.add(type);}if(!text(adm).isBlank()){q+=" AND sm.registration_no LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" GROUP BY sm.registration_no,sm.stu_id,so.first_name,so.last_name,cn.class_name,cl.section ORDER BY className,section,studentName",p.toArray());}
    private List<Map<String,Object>> reconciliation(String sc,String ses,String from,String to,String adm,String status){String q="SELECT row_id AS id,COALESCE(receipt_no,receiptno) AS receiptNo,admno,COALESCE(pay_date,paymentdate,deposit_date) AS paymentDate,COALESCE(pay_mode,mop,'') AS payMode,transaction_no AS transactionNo,amount,COALESCE(reconsillation_status,'Pending') AS reconciliationStatus,COALESCE(Bounce_reason,'') AS bounceReason,status FROM fee_payment_detail WHERE school_id=? AND session=?";List<Object>p=new ArrayList<>(List.of(sc,ses));if(!text(status).isBlank()&&!"all".equalsIgnoreCase(status)){q+=" AND COALESCE(reconsillation_status,'Pending')=?";p.add(status);}if(!text(from).isBlank()){q+=" AND TRY_CONVERT(date,COALESCE(pay_date,paymentdate,deposit_date))>=TRY_CONVERT(date,?)";p.add(from);}if(!text(to).isBlank()){q+=" AND TRY_CONVERT(date,COALESCE(pay_date,paymentdate,deposit_date))<=TRY_CONVERT(date,?)";p.add(to);}if(!text(adm).isBlank()){q+=" AND admno LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" ORDER BY row_id DESC",p.toArray());}
    private List<Map<String,Object>> installmentDefaulter(String sc,String ses,Integer classId,Integer inst,Integer type,String adm){String q="SELECT l.installment_no AS installmentNo,COALESCE(i.installment_dis,'') AS installmentName,COUNT(DISTINCT l.stu_id) AS students,SUM(COALESCE(l.payable,0)) AS payable,SUM(COALESCE(l.receive_amount,0)) AS received,SUM(COALESCE(l.balance,0)) AS balance FROM fee_student_ledger l LEFT JOIN Installment_Master i ON i.school_id=l.school_id AND i.session=l.session AND i.installment_no=l.installment_no AND i.fee_type_id=l.fee_type_id LEFT JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id WHERE l.school_id=? AND l.session=? AND COALESCE(l.balance,0)>0";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(inst!=null){q+=" AND l.installment_no=?";p.add(inst);}if(type!=null){q+=" AND l.fee_type_id=?";p.add(type);}if(!text(adm).isBlank()){q+=" AND sm.registration_no LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" GROUP BY l.installment_no,i.installment_dis ORDER BY l.installment_no",p.toArray());}
    private List<Map<String,Object>> lateFee(String sc,String ses,Integer classId,String adm){String q="SELECT sm.registration_no AS admissionNo,sm.stu_id AS studentId,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,d.inst_no AS installmentNo,SUM(COALESCE(d.late_fee,0)) AS lateFee,SUM(COALESCE(d.dip_amt,0)) AS received,SUM(COALESCE(d.late_fee,0)-COALESCE(d.dip_amt,0)) AS balance FROM stu_fee_deposit d JOIN TB_StudentMaster sm ON sm.school_id=d.school_id AND sm.stu_id=d.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE d.school_id=? AND d.session=? AND COALESCE(d.late_fee,0)>0";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null){q+=" AND sm.class_id=?";p.add(classId);}if(!text(adm).isBlank()){q+=" AND sm.registration_no LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" GROUP BY sm.registration_no,sm.stu_id,so.first_name,so.last_name,cn.class_name,cl.section,d.inst_no ORDER BY className,section,studentName",p.toArray());}
    private List<Map<String,Object>> paymentResponse(String sc,String ses,String from,String to,String status,String adm){String q="SELECT id,order_id AS orderId,tracking_id AS trackingId,bank_ref_no AS bankRefNo,order_status AS orderStatus,failure_message AS failureMessage,payment_mode AS paymentMode,amount,username,posteddate,stu_id AS studentId,session,gatewayname AS gateway,invoiceNumber FROM PaymentResponse WHERE school_id=? AND session=?";List<Object>p=new ArrayList<>(List.of(sc,ses));if(!text(status).isBlank()&&!"all".equalsIgnoreCase(status)){q+=" AND order_status=?";p.add(status);}if(!text(from).isBlank()){q+=" AND CONVERT(date,posteddate)>=CONVERT(date,?)";p.add(from);}if(!text(to).isBlank()){q+=" AND CONVERT(date,posteddate)<=CONVERT(date,?)";p.add(to);}if(!text(adm).isBlank()){q+=" AND username LIKE ?";p.add("%"+text(adm)+"%");}return jdbc.queryForList(q+" ORDER BY posteddate DESC,id DESC",p.toArray());}
    private List<Map<String,Object>> studentSummary(String sc,String ses,String adm){return jdbc.queryForList("SELECT sm.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(cn.class_name,'') AS className,COALESCE(cl.section,'') AS section,l.session,l.installment_no AS installmentNo,COALESCE(h.fee_head,'') AS feeHead,l.head_amount AS headAmount,l.concession,l.payable,l.receive_amount AS received,l.balance FROM fee_student_ledger l JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id LEFT JOIN fee_head_master h ON h.school_id=l.school_id AND h.session=l.session AND h.fee_head_id=l.fee_head_id WHERE l.school_id=? AND l.session=? AND sm.registration_no LIKE ? ORDER BY l.installment_no,l.fee_head_id",sc,ses,"%"+text(adm)+"%");}
}
